    const actualExtraTime=input.extraTimePlayed===true||['extra-first','extra-break','extra-second'].includes(clockRows()[matchId]?.phase)||Object.keys(clockRows()[matchId]?.completedPhases||{}).some(phase=>phase.startsWith('extra-'));
