    const suffix=identity.team(match.homeTeamId)?.id.split('-').at(-1)||fixtures().cups.find(cup=>cup.id===match.tournamentId)?.suffix||(match.cupKey==='jeugd'?'15':match.cupKey==='vrouwen'?'V1':match.cupKey==='o23'?'23':'01');
