  function saveOfficialAvailability(id,date,input){const person=officials().find(x=>x.id===id);if(!person||!validDate(date))return fail('Kies een official en geldige datum.');if(!allowed('arbitration.availability',{officialId:id}))return fail('Je mag alleen de eigen beschikbaarheid beheren.');const value={officialId:id,date,available:input.available!==false,from:input.from||person.from,until:input.until||person.until,note:text(input.note).slice(0,300),at:now()};if(!validTime(value.from)||!validTime(value.until)||minute(value.from)>=minute(value.until))return fail('Kies een geldige begin- en eindtijd.');const rows=read('operationsOfficialAvailability',{}),before=rows[id]?.[date];store.set('operationsOfficialAvailability',{...rows,[id]:{...rows[id],[date]:value}});const affected=base.assignments().filter(a=>a.officialId===id&&a.confirmed&&F.get(a.matchId)?.date===date&&!availability(a.matchId,id).ok);if(affected.length)notify('Beschikbaarheid raakt bevestigde aanstelling',person.name+' · '+affected.length+' aanstelling(en) vragen herbeoordeling.',{role:'leadership',href:'#arbitrage',officialId:id,type:'assignment'});audit('OFFICIAL_AVAILABILITY_CHANGED',id,before,value,'Beschikbaarheid per datum bijgewerkt');emit('official');return {ok:true,availability:value,affected:affected.map(x=>x.matchId)};}
  function availability(matchId,id){const matchRows=F.all(),match=matchRows.find(m=>m.id===matchId),person=officials().find(x=>x.id===id);if(!match||!person)return fail('Kies een wedstrijd en scheidsrechter.');const suffix=I.team(match.homeTeamId)?.id.split('-').at(-1)||F.cups.find(c=>c.id===match.tournamentId)?.suffix||'01';if(!person.categories.includes(suffix))return fail('Deze official is niet bevoegd voor deze categorie.');const avail=officialAvailability(id,match.date);if(!avail.available||minute(match.time)<minute(avail.from)||minute(match.time)+duration(match)>minute(avail.until))return fail('De aftrap valt buiten de beschikbaarheid op deze datum.');const rules=window.HVCompetition?.rulesForMatch(match)?.rules||{};if(rules.refereeType==='neutral'&&(person.clubIds||[]).some(c=>[match.homeClubId,match.awayClubId].includes(c)))return fail('Een neutrale official mag niet verbonden zijn aan een van de spelende verenigingen.');for(const other of base.assignments()){if(other.matchId===matchId||other.officialId!==id||['declined','cancelled'].includes(other.status))continue;const game=matchRows.find(m=>m.id===other.matchId);if(!game||game.date!==match.date||['cancelled','bye','walkover'].includes(game.status))continue;const buffer=travel(game.venue,match.venue),start=minute(match.time),otherStart=minute(game.time);if(start<otherStart+duration(game)+buffer&&otherStart<start+duration(match)+buffer)return fail('Dubbele aanstelling of onvoldoende reistijd ('+buffer+' min): '+game.home+' – '+game.away+'.');}return {ok:true,official:person,availability:avail};}
  function saveAssignment(matchId,value,action,reason){const before=base.assignment(matchId);store.set('operationsAssignments',{...read('operationsAssignments',{}),[matchId]:value});const sessions=read('officialMatchSessions',{});store.set('officialMatchSessions',{...sessions,[matchId]:{...sessions[matchId],confirmed:value.confirmed}});if(F.get(matchId)?.isPrimary){store.set('officialSession',{...read('officialSession',{}),confirmed:value.confirmed});store.set('arbitration',{...read('arbitration',{}),featured:{...value,id:value.officialId},name:value.name,confirmed:value.confirmed});}audit(action,matchId,before,value,reason);emit('assignment');return {ok:true,assignment:copy(value)};}
  function assign(matchId,id,reason='',options={}){const match=F.get(matchId);if(!match)return fail('Wedstrijd niet gevonden.');const gate=guard(match);if(!gate.ok)return gate;if(!allowed('arbitration.manage',{matchId,cupId:match.tournamentId}))return fail('Je mag deze aanstelling niet beheren.');if(['live','finished','suspended','walkover'].includes(match.status))return fail('Gebruik de vastgelegde noodvervanging voor een begonnen wedstrijd.');const check=availability(matchId,id);if(!check.ok)return check;const before=base.assignment(matchId),kick=Date.parse(window.HVClock?.instant?.(match.date,match.time)||match.date+'T'+match.time+':00+02:00'),deadline=options.responseDue||new Date(Math.max(Date.parse(now())+30*60000,kick-24*3600000)).toISOString();if(!Number.isFinite(Date.parse(deadline)))return fail('Kies een geldige reactietermijn.');const value={...before,matchId,officialId:id,name:check.official.name,status:'pending',confirmed:false,at:now(),responseDue:deadline,history:[{at:now(),text:'Aangesteld: '+check.official.name+(text(reason)?' · '+text(reason):'')},...(before?.history||[])]};const result=saveAssignment(matchId,value,'OFFICIAL_ASSIGNED',reason);notify('Nieuwe aanstelling',match.home+' – '+match.away+' · bevestig of weiger vóór de reactietermijn.',{role:'official',officialId:id,matchId,cupId:match.tournamentId,href:'#official',type:'assignment',requiresConfirmation:true});return result;}
  function confirmAssignment(matchId){const match=F.get(matchId),before=base.assignment(matchId);if(!match||!before?.officialId)return fail('Er staat geen aanstelling klaar.');const gate=guard(match);if(!gate.ok)return gate;if(!allowed('arbitration.respond',{matchId,officialId:before.officialId}))return fail('Alleen de aangestelde official kan deze aanstelling bevestigen.');const check=availability(matchId,before.officialId);if(!check.ok)return check;return saveAssignment(matchId,{...before,status:'confirmed',confirmed:true,confirmedAt:now(),history:[{at:now(),text:'Aanstelling bevestigd door '+before.name},...(before.history||[])]},'OFFICIAL_CONFIRMED','Aanstelling geaccepteerd');}
