  const planProposals=()=>read('operationsPlanProposals',[]);
  function proposePlan(matchId,changes,reason=''){const gate=guard(F.get(matchId));if(!gate.ok)return gate;if(!allowed('planning.manage',{matchId}))return fail('Je mag de wedstrijdplanning niet aanpassen.');const impact=planningImpact(matchId,changes);if(!impact.ok)return {...impact,error:impact.blockers[0]};const value={id:uid('HV-PLAN'),...impact,status:'draft',reason:text(reason),at:now()};store.set('operationsPlanProposals',[value,...planProposals()].slice(0,100));emit('planning');return {ok:true,proposal:value};}
  function publishPlan(id,reason){const proposal=planProposals().find(x=>x.id===id);if(!proposal||proposal.status!=='draft')return fail('Dit voorstel staat niet meer open.');if(text(reason).length<8)return fail('Bevestig het wijzigingsvoorstel met een duidelijke reden.');const match=F.get(proposal.matchId);if(!match||['date','time','field','status'].some(k=>match[k]!==proposal.before[k]))return fail('De planning is ondertussen gewijzigd. Maak een nieuw voorstel.');const impact=planningImpact(proposal.matchId,proposal.proposed);if(!impact.ok)return {...impact,error:impact.blockers[0]};const result=F.moveFixture(proposal.matchId,proposal.proposed);if(!result.ok)return result;store.set('operationsPlanProposals',planProposals().map(x=>x.id===id?{...x,status:'published',reason:text(reason),publishedAt:now()}:x));notify('Nieuwe wedstrijdafspraak',match.home+' – '+match.away+' · '+proposal.proposed.date+' '+proposal.proposed.time,{role:'all',teamIds:[match.homeTeamId,match.awayTeamId],officialId:base.assignment(match.id)?.officialId,matchId:match.id,cupId:match.tournamentId,requiresConfirmation:true,href:'#wedstrijd-'+match.id,type:'fixture'});audit('PLANNING_PROPOSAL_PUBLISHED',match.id,proposal.before,proposal.proposed,reason);emit('planning');return result;}
  function proposeFixtureChange(matchId,input={}){const match=F.get(matchId);if(!match||match.status!=='scheduled'||!match.homeTeamId||!match.awayTeamId)return fail('Kies een nog te spelen wedstrijd met twee bekende deelnemers.');const gate=guard(match);if(!gate.ok)return gate;const c=context(),own=input.requesterTeamId||([match.homeTeamId,match.awayTeamId].find(id=>c.teamIds.includes(id)||c.clubIds.includes(I.team(id)?.clubId)))||match.homeTeamId;if(![match.homeTeamId,match.awayTeamId].includes(own)||!allowed('operations.propose',{matchId,teamId:own}))return fail('Je mag alleen een voorstel voor je eigen team indienen.');if(base.changes().some(x=>x.matchId===matchId&&['requested','opponent-approved'].includes(x.status)))return fail('Er staat al een wijzigingsvoorstel open voor dit duel.');if(text(input.reason).length<8||text(input.reason).length>600)return fail('Geef een duidelijke reden van 8 tot 600 tekens.');const options=(Array.isArray(input.options)?input.options:[input]).slice(0,3).map(x=>({date:x.date,time:text(x.time).replace('.',':'),field:text(x.field)}));if(!options.length)return fail('Geef ten minste één speeloptie op.');for(const p of options){const impact=planningImpact(matchId,p);if(!impact.ok)return {...impact,error:impact.blockers[0]};}const value={id:uid('HV-CHANGE'),matchId,cupId:match.tournamentId,homeTeamId:match.homeTeamId,awayTeamId:match.awayTeamId,requesterTeamId:own,respondentTeamId:own===match.homeTeamId?match.awayTeamId:match.homeTeamId,before:{date:match.date,time:match.time,field:match.field},proposed:options[0],options,reason:text(input.reason),status:'requested',at:now(),version:1,history:[{at:now(),text:(I.team(own)?.name||'Team')+' heeft een wijzigingsvoorstel ingediend.'}]};store.set('operationsChanges',[value,...base.changes()]);notify('Voorstel voor een nieuwe aftrap',match.home+' – '+match.away+' · '+value.reason,{role:'club',teamIds:[value.respondentTeamId],matchId,href:'#club',type:'fixture',requiresConfirmation:true});audit('FIXTURE_CHANGE_REQUESTED',matchId,value.before,value.proposed,value.reason);emit('change');return {ok:true,change:value};}
  function approveChangeOpponent(id,optionIndex=0){const value=base.changes().find(x=>x.id===id);if(!value||value.status!=='requested')return fail('Dit voorstel wacht niet op de tegenstander.');const respondent=value.respondentTeamId||value.awayTeamId;if(!allowed('operations.change',{matchId:value.matchId,teamId:respondent}))return fail('Alleen de andere betrokken vereniging kan deze optie bevestigen.');const option=value.options?.[optionIndex]||value.proposed;if(!option)return fail('Kies een voorgestelde speeloptie.');const impact=planningImpact(value.matchId,option);if(!impact.ok)return {...impact,error:impact.blockers[0]};const next={...value,status:'opponent-approved',proposed:option,opponentApprovedAt:now(),history:[{at:now(),text:(I.team(respondent)?.name||'Andere team')+' akkoord. Toernooileiding beoordeelt de optie.'},...value.history]};store.set('operationsChanges',base.changes().map(x=>x.id===id?next:x));notify('Wedstrijdvoorstel ter beoordeling',next.reason,{role:'leadership',matchId:next.matchId,href:'#club',type:'fixture'});audit('FIXTURE_CHANGE_OPPONENT_APPROVED',next.matchId,value.status,next.status,'Akkoord van de andere vereniging');emit('change');return {ok:true,change:next};}
  function counterChange(id,input){const value=base.changes().find(x=>x.id===id);if(!value||value.status!=='requested')return fail('Alleen een open voorstel kan een tegenvoorstel krijgen.');const responder=value.respondentTeamId||value.awayTeamId;if(!allowed('operations.change',{matchId:value.matchId,teamId:responder}))return fail('Je mag dit voorstel niet namens de tegenstander beantwoorden.');if(text(input.reason).length<8)return fail('Geef een duidelijke reden voor het tegenvoorstel.');const proposed={date:input.date,time:text(input.time).replace('.',':'),field:text(input.field)},impact=planningImpact(value.matchId,proposed);if(!impact.ok)return {...impact,error:impact.blockers[0]};const next={...value,requesterTeamId:responder,respondentTeamId:value.requesterTeamId||value.homeTeamId,proposed,options:[proposed],reason:text(input.reason),version:(value.version||1)+1,history:[{at:now(),text:(I.team(responder)?.name||'Andere team')+' doet een tegenvoorstel: '+text(input.reason)},...value.history]};store.set('operationsChanges',base.changes().map(x=>x.id===id?next:x));notify('Tegenvoorstel ontvangen',next.reason,{role:'club',teamIds:[next.respondentTeamId],matchId:next.matchId,href:'#club',type:'fixture',requiresConfirmation:true});emit('change');return {ok:true,change:next};}
  function decideChange(id,approved,reason){const value=base.changes().find(x=>x.id===id);if(!value)return fail('Voorstel niet gevonden.');if(!allowed('planning.manage',{matchId:value.matchId}))return fail('Alleen toernooileiding kan de speelafspraak vaststellen.');if(approved){const impact=planningImpact(value.matchId,value.proposed);if(!impact.ok)return {...impact,error:impact.blockers[0]};}const r=base.decideChange(id,approved,reason);if(r.ok&&approved)notify('Nieuwe aftrap actief bevestigen',reason,{role:'all',matchId:value.matchId,teamIds:[value.homeTeamId,value.awayTeamId],officialId:base.assignment(value.matchId)?.officialId,href:'#wedstrijd-'+value.matchId,type:'fixture',requiresConfirmation:true});return r;}
  function finalProgress(matchId){const match=F.get(matchId);return match?{matchId,plannedKickoff:match.time,expectedKickoff:match.time,expectedEnd:clock(minute(match.time)+duration(match)),actualKickoff:null,actualEnd:null,status:'planned',...read('operationsFinalProgress',{})[matchId]}:null;}
  function recordFinalProgress(matchId,input){const match=F.get(matchId);if(!match||match.roundKey!=='final')return fail('Kies een finale.');const gate=guard(match);if(!gate.ok)return gate;if(!allowed('finals.manage',{matchId}))return fail('Je mag de finaledagregie niet aanpassen.');const before=finalProgress(matchId),next={...before,...input,at:now()};for(const key of ['expectedKickoff','expectedEnd','actualKickoff','actualEnd'])if(next[key]&&!validTime(next[key]))return fail('Gebruik geldige tijden voor verwacht en werkelijk verloop.');if(!['planned','ready','running','finished','delayed'].includes(next.status))return fail('Kies een geldige regiestatus.');if(next.actualEnd&&next.actualKickoff&&minute(next.actualEnd)<minute(next.actualKickoff))return fail('Het werkelijke einde moet na de aftrap liggen.');store.set('operationsFinalProgress',{...read('operationsFinalProgress',{}),[matchId]:next});audit('FINAL_PROGRESS_CHANGED',matchId,before,next,text(input.reason)||'Werkelijk verloop vastgelegd');emit('final');return {ok:true,progress:next};}
