  function setVolunteerAvailability(id,input){if(!ownVolunteer(id))return fail('Je mag alleen je eigen beschikbaarheid wijzigen.');const person=volunteers().find(p=>p.id===id);if(!person)return fail('Kies een vrijwilliger.');if(!validTime(input.from)||!validTime(input.until)||minute(input.from)>=minute(input.until))return fail('Kies geldige beschikbaarheid.');for(const row of core.shiftSignups().filter(x=>x.personId===id&&x.status!=='waiting')){const shift=shifts().find(s=>s.id===row.shiftId);if(shift&&(minute(shift.from)<minute(input.from)||minute(shift.until)>minute(input.until)))return fail('Je bent al ingeschreven buiten dit tijdvenster. Regel eerst vervanging of meld je af.');}store.set('operationsVolunteerAvailability',{...read('operationsVolunteerAvailability',{}),[id]:{from:input.from,until:input.until}});emit('volunteer');return {ok:true};}
