  function inScope(item,ctx){const c=context(ctx),roles=(item.roles||[item.role||'all']).map(alias);if(item.accountIds?.length&&!item.accountIds.includes(c.accountId))return false;const ownPlayerUpdate=c.role==='player'&&roles.includes('team')&&['fixture','result','roster','planning','lineup'].includes(item.type);if(!roles.includes('all')&&!roles.includes(c.role)&&c.role!=='leadership'&&!ownPlayerUpdate)return false;if(c.role==='leadership')return true;if(item.officialId&&c.role==='official'&&item.officialId!==c.officialId)return false;if(item.personId&&c.role==='volunteer'&&item.personId!==c.personId)return false;const teams=item.teamIds||[item.teamId].filter(Boolean),clubs=item.clubIds||[item.clubId].filter(Boolean);if(['team','player'].includes(c.role)&&teams.length&&!teams.some(id=>c.teamIds.includes(id)))return false;if(c.role==='club'){const scopeClubs=[...clubs,...teams.map(id=>I.team(id)?.clubId).filter(Boolean)];if(scopeClubs.length&&!scopeClubs.some(id=>c.clubIds.includes(id)))return false;}if(c.role==='official'&&item.matchId){const assigned=base.assignment(item.matchId);if(assigned?.officialId!==c.officialId)return false;}return true;}
