  function markRead(id,readValue=true,ctx){if(window.HVAccess&&ctx?.accountId&&ctx.accountId!==window.HVAccess.current().id)return fail('Een leesbevestiging hoort bij het eigen account.');const visible=inboxFor(ctx).some(x=>x.id===id);if(!visible&&window.HVAccess)return fail('Dit bericht is niet voor dit account bestemd.');setReceipt(id,{read:readValue===true,status:readValue?'read':'delivered',deliveredAt:receipt(id,ctx).deliveredAt||now(),readAt:readValue?now():null},ctx);return {ok:true};}
