  function preferencesFor(id){if(!canonicalPreferences){canonicalPreferences=new Map();for(const [personId,value]of Object.entries(read().players||{})){const key=canonical(personId),before=canonicalPreferences.get(key);if(!before){canonicalPreferences.set(key,{...value});continue;}const next={...before,...value};for(const field of ['name','photo','statistics','press'])if(typeof before[field]==='boolean'&&typeof value[field]==='boolean')next[field]=before[field]&&value[field];next.retentionUntil=[before.retentionUntil,value.retentionUntil].filter(Boolean).sort()[0];canonicalPreferences.set(key,next);}}return canonicalPreferences.get(canonical(id))||{};}
