  function players(){if(peopleCache)return peopleCache;const rows=window.HVRegistrations?.allRosters?.().flatMap(roster=>roster.players.map(person=>({...person,cupId:roster.cupId,teamId:roster.teamId,clubId:roster.clubId})))||window.HVMatchCenter?.allPlayers?.()||[],map=new Map();for(const row of rows){const id=canonical(row.hvId||row.id),old=map.get(id);map.set(id,{...row,id,hvId:id,aliases:[...new Set([...(old?.aliases||[]),row.id,row.hvId].filter(Boolean))],cupIds:[...new Set([...(old?.cupIds||[]),row.cupId].filter(Boolean))],teamIds:[...new Set([...(old?.teamIds||[]),row.teamId].filter(Boolean))]});}peopleCache=[...map.values()];peopleIndex=new Map();for(const person of peopleCache)for(const key of [person.id,person.hvId,person.legacyId,...(person.aliases||[])].filter(Boolean))peopleIndex.set(key,person);return peopleCache;}
