  function publicPlayer(player,context={}){if(!player)return null;const id=player.hvId||player.id,prefs=consent(player),rules=publicationSettings(player,context);if(!prefs.statistics||(prefs.retentionUntil&&prefs.retentionUntil<now().slice(0,10)))return null;const allowedName=prefs.name&&rules.names,number=rules.numbers?Number(player.number||player.shirtNumber)||null:null,name=allowedName?(player.name||[player.firstName,player.lastName].filter(Boolean).join(' ')):number?'Speler '+number:'Speler';return {id,teamId:player.teamId||context.teamId,clubId:player.clubId,name,displayName:name,photo:prefs.photo&&allowedName&&player.photo?player.photo:'assets/hv-app-192.png',number,allowed:true,nameVisible:allowedName,photoVisible:!!(prefs.photo&&allowedName&&player.photo),statistics:true,press:!!(prefs.press&&rules.pressNames)};}
