  function canPublishLineup(matchOrId,side,purpose='public'){const match=typeof matchOrId==='string'?window.HVFixtures?.get(matchOrId):matchOrId;if(!match)return false;const settings=cupSettings(match.tournamentId),flag=purpose==='press'?'pressLineups':'lineups';if(!settings[flag])return false;const review=window.HVRegistrations?.reviewState?.(match.id,side);if(review?.status!=='approved')return false;if(['live','finished','suspended'].includes(match.status))return true;const kickoff=window.HVClock?.instant?.(match.date,match.time)||match.date+'T'+match.time+':00+02:00';return Date.parse(now())>=Date.parse(kickoff)-Number(settings.lineupEmbargoMinutes??30)*60000;}
  function saveCup(value,input){if(window.HVAccess&&!window.HVAccess.can('privacy.manage',{cupId:value}))return fail('Alleen de toernooileiding beheert publicatierechten.');const cup=window.HVFixtures?.cups.find(c=>c.id===value||c.key===value);if(!cup)return fail('Kies een toernooi.');const before=cupSettings(cup.id),next={};for(const field of Object.keys(baseCup)){if(typeof input[field]!=='boolean')return fail('Vul alle publicatiekeuzes in.');next[field]=input[field];}next.lineupEmbargoMinutes=Number(input.lineupEmbargoMinutes??before.lineupEmbargoMinutes??30);if(!Number.isInteger(next.lineupEmbargoMinutes)||next.lineupEmbargoMinutes<0||next.lineupEmbargoMinutes>120)return fail('Kies een publicatievenster van 0 tot en met 120 minuten vóór de aftrap.');store.set('privacySettings',{...read(),cups:{...read().cups,[cup.id]:next}});window.HVWorkflow?.audit('PUBLICATIERECHTEN_GEWIJZIGD',cup.id,before,next,'Vrijgave per doelgroep aangepast.');return {ok:true,settings:next};}
