  function visible(row,right='website'){return row.status==='approved'&&row.rights?.[right]&&(!row.expiresAt||row.expiresAt>=now().slice(0,10))&&canPublish('media',{cupId:row.cupId,matchId:row.matchId});}
  function project(row){return {id:row.id,matchId:row.matchId,cupId:row.cupId,clubId:row.clubId,teamId:row.teamId,title:row.title,type:row.type,src:safeSource(row.src)?row.src:'assets/action.webp',credit:row.credit,rights:clone(row.rights),filename:row.filename,previewOnly:row.previewOnly===true,expiresAt:row.expiresAt||null,originalAvailable:!!row.originalSrc||!row.previewOnly,example:true};}
