  const $=s=>root.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const labels={scheduled:'Gepland',live:'Live',paused:'Rust',finished:'Afgelopen',cancelled:'Afgelast',suspended:'Gestaakt',review:'In beoordeling',bye:'Vrijloting',walkover:'Reglementair beslist'};
  const eventNames={goal:'Doelpunt','penalty-goal':'Benutte strafschop','own-goal':'Eigen doelpunt',yellow:'Gele kaart','second-yellow':'Tweede gele kaart',red:'Rode kaart',substitution:'Wissel',incident:'Bijzonderheid',resumed:'Hervat',half_time:'Rust'};
  const eventIcons={goal:'●','penalty-goal':'●','own-goal':'●',yellow:'▮','second-yellow':'▮',red:'▮',substitution:'⇄',incident:'!'};
