  function render(){selectedFromRoute();const match=fixtures.get(selected)||fixtures.all()[0];if(!match)return;selected=match.id;choices(match);if(routeUnknown)$('[data-mc-feedback]').textContent='Deze wedstrijd is niet gevonden. Kies hierboven een bestaand duel.';else if($('[data-mc-feedback]').textContent.startsWith('Deze wedstrijd is niet gevonden.'))$('[data-mc-feedback]').textContent='';score(match);const players=safePlayers(match),events=core.events(match.id).filter(row=>row.status!=='rejected');timeline(match,events,players);lineups(match);media(match);window.HVCompetitionUI?.renderMatchBrief($('[data-mc-brief]'),match);const follow=$('[data-mc-follow]'),followed=window.HVFollowing?.has('match',match.id)||false;follow.dataset.followId=match.id;follow.textContent=followed?'Gevolgd':'Volgen';follow.setAttribute('aria-pressed',String(followed));$('[data-mc-bracket]').href='#schema-'+match.cupKey;root.querySelectorAll('[data-mc-tab]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.mcTab===tab)));root.querySelectorAll('[data-mc-panel]').forEach(panel=>panel.hidden=panel.dataset.mcPanel!==tab);const hero=root.querySelector('.hv-page-hero');if(hero){const title=hero.querySelector('h1');if(title)title.textContent=match.home+' – '+match.away;const eyebrow=hero.querySelector('.hv-hero__eyebrow');if(eyebrow)eyebrow.textContent=match.cupName+' · '+match.round;}const signature=match.id+'|'+events.map(row=>row.id+row.status).join(',');if(signature!==lastSignature&&lastSignature&&!matchMedia('(prefers-reduced-motion: reduce)').matches)$('[data-mc-events]').animate([{opacity:.6},{opacity:1}],{duration:200});lastSignature=signature;}
  $('[data-mc-cup]').addEventListener('change',e=>{const games=fixtures.forCup(e.target.value),match=games.find(row=>row.date>=fixtures.today)||games[0];if(match)location.hash='wedstrijd-'+match.id;else{e.target.value=fixtures.get(selected)?.tournamentId||'';$('[data-mc-feedback]').textContent='Voor deze beker staat nog geen wedstrijd gepland.';}});$('[data-mc-match]').addEventListener('change',e=>location.hash='wedstrijd-'+e.target.value);
  root.addEventListener('click',e=>{const button=e.target.closest('[data-mc-tab]');if(button){tab=button.dataset.mcTab;render();}if(e.target.closest('[data-mc-sort]')){latest=!latest;$('[data-mc-sort]').textContent=latest?'Laatste eerst':'Eerste eerst';render();}});
  $('[data-mc-calendar]').addEventListener('click',()=>{const match=fixtures.get(selected);if(!match)return;const text=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//HV Control//Wedstrijd//NL','BEGIN:VEVENT','UID:'+match.id+'@hv-control','DTSTART;TZID=Europe/Amsterdam:'+match.date.replaceAll('-','')+'T'+match.time.replace(':','')+'00','SUMMARY:'+(match.home+' – '+match.away).replace(/[;,\n]/g,' '),'LOCATION:'+(match.venue+' · '+match.field).replace(/[;,\n]/g,' '),'END:VEVENT','END:VCALENDAR'].join('\r\n'),url=URL.createObjectURL(new Blob([text],{type:'text/calendar;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download='HV-wedstrijd.ics';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('[data-mc-feedback]').textContent='De afspraak staat klaar als agendabestand.';});
  $('[data-mc-share]').addEventListener('click',async()=>{const match=fixtures.get(selected);if(!match)return;const url=new URL(location.href);url.hash='wedstrijd-'+match.id;try{if(navigator.share)await navigator.share({title:match.home+' – '+match.away,url:url.href});else{await navigator.clipboard.writeText(url.href);$('[data-mc-feedback]').textContent='De wedstrijdlink is gekopieerd.';}}catch(error){if(error.name!=='AbortError')$('[data-mc-feedback]').textContent='Deel de wedstrijd door de link uit je adresbalk te kopiëren.';}});
