  const labels={finished:'Officiële uitslag',walkover:'Reglementair beslist',cancelled:'Afgelast',suspended:'Gestaakt · besluit volgt',review:'In beoordeling'};
  function rows(){return fixtures.all().filter(game=>(!filter.value||game.tournamentId===filter.value)&&Object.hasOwn(labels,game.status)).sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time));}
