  function renderPlayers(){const game=fixtures.get(matchSelect.value),privacy=window.HVPrivacy;if(!game||!privacy)return;const context={cupId:game.tournamentId,matchId:game.id},settings=privacy.cupSettings(context);$('[data-press-permissions]').innerHTML=[['Namen',settings.pressNames],['Rugnummers',settings.pressNumbers],['Opstellingen',settings.pressLineups]].map(([name,yes])=>'<span>'+name+': '+(yes?'Vrijgegeven':'Afgeschermd')+'</span>').join('');if(!settings.pressLineups){$('[data-press-players]').innerHTML='<p class="media-empty">De opstellingen van deze beker zijn nog niet voor de pers vrijgegeven.</p>';return;}const rows=['home','away'].flatMap(side=>(!privacy.canPublishLineup(game,side,'press')?[]:(window.HVMatchCenter?.players(game.id,side)||[])).map(player=>{const safe=privacy.pressPlayer(player,context);return safe?{...safe,teamName:game[side]}:null;}).filter(Boolean));$('[data-press-players]').innerHTML=rows.map(player=>'<article class="media-press-person"><img src="'+esc(player.photo)+'" alt="Foto bij vrijgegeven spelersgegevens"><div><strong>'+esc((player.number?player.number+' · ':'')+player.name)+'</strong><small>'+esc(player.teamName)+'</small></div></article>').join('')||'<p class="media-empty">Voor deze opstelling zijn nog geen spelersgegevens voor de pers beschikbaar.</p>';}
  function renderMedia(){const rows=(window.HVMedia?.published('articles')||[]).filter(row=>!filter.value||row.cupId===filter.value);$('[data-press-media]').innerHTML=rows.map(row=>'<article class="media-library-card"><img src="'+esc(row.src)+'" alt="'+esc(row.title)+'" loading="lazy"><div class="media-library-copy"><h3>'+esc(row.title)+'</h3><p>Credit: '+esc(row.credit)+'</p><div class="media-rights-tags"><span>Artikelen toegestaan</span>'+(row.rights.social?'<span>Sociale kanalen toegestaan</span>':'<span>Geen toestemming voor sociale kanalen</span>')+'</div>'+(row.type==='image'?'<button type="button" class="hv-button hv-button-outline" data-press-media-download="'+esc(row.id)+'">'+(row.previewOnly?'Download demopreview':'Download beeld')+'</button>':'<p>Videometadata geregistreerd; het origineel is in deze demo niet opgeslagen.</p>')+'</div></article>').join('')||'<p class="media-empty">Er is nog geen beeld met gebruiksrecht voor artikelen vrijgegeven.</p>';}
  function render(){const old=filter.value;filter.innerHTML='<option value="">Alle bekers</option>'+fixtures.cups.map(cup=>'<option value="'+esc(cup.id)+'">'+esc(cup.name)+'</option>').join('');filter.value=old;renderResults();renderMatches();renderMedia();}
  root.addEventListener('click',event=>{const button=event.target.closest('[data-press-media-download]');if(!button)return;const result=window.HVMedia.downloadInfo(button.dataset.pressMediaDownload,'articles');if(!result.ok){$('[data-press-message]').textContent=result.error;renderMedia();return;}const a=document.createElement('a');a.href=result.src;a.download=result.originalAvailable?result.filename:'preview-'+result.filename;document.body.append(a);a.click();a.remove();});
  $('[data-press-package]').addEventListener('click',async()=>{const button=$('[data-press-package]'),feedback=$('[data-press-package-feedback]');button.disabled=true;feedback.textContent='Het beeldpakket wordt samengesteld.';const result=await window.HVMedia.packageForMatch(matchSelect.value,'articles');button.disabled=false;if(!result.ok){feedback.textContent=result.error;return;}const url=URL.createObjectURL(result.blob),a=document.createElement('a');a.href=url;a.download=result.filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);feedback.textContent=result.count+' beelden met credits en gebruiksrechten gedownload.';});
  const official=()=>rows().filter(game=>['finished','walkover'].includes(game.status));
  const text=()=>['Haaglanden Voetbal · Officiële uitslagen (demo)','',...official().map(game=>[game.cupName,game.home+' – '+game.away,result(game),game.date,game.venue].join(' · '))].join('\n');
