  $('[data-press-prev]').addEventListener('click',()=>{page--;renderResults();});$('[data-press-next]').addEventListener('click',()=>{page++;renderResults();});filter.addEventListener('change',()=>{page=0;renderResults();renderMatches();renderMedia();});matchSelect.addEventListener('change',renderPlayers);
  const requestForm=$('[data-press-request]');function showRequest(){const item=window.HVDemo.get('pressRequests',[])[0];$('[data-press-request-feedback]').textContent=item?'Ingediend (demo) · '+item.medium+' · '+({pending:'Wacht op beoordeling',approved:'Goedgekeurd',rejected:'Afgewezen'})[item.status]:'Nog geen persverzoek in deze demo.';}
  requestForm.addEventListener('submit',event=>{event.preventDefault();const name=requestForm.elements.name.value.trim(),medium=requestForm.elements.medium.value.trim();if(!name||!medium)return;const item={id:'HV-PERS-'+crypto.randomUUID().toUpperCase(),name,medium,coverage:requestForm.elements.coverage.value,status:'pending',createdAt:new Date().toISOString()};window.HVDemo.set('pressRequests',[item,...window.HVDemo.get('pressRequests',[])]);window.HVWorkflow?.notify('Nieuwe persaanmelding',medium+' · '+item.coverage,{href:'#privacy',role:'leadership'});showRequest();});
