    const cup=cups.find(c=>c.id===cupId),used=[...new Set([...(cup?.teamIds||[]),...fixtures.forCup(cupId).flatMap(g=>[g.homeTeamId,g.awayTeamId]),...core.allRosters().filter(r=>r.cupId===cupId).map(r=>r.teamId)].filter(Boolean))];const teams=used.map(ids.team).filter(Boolean).filter(t=>!window.HVAccess||window.HVAccess.can('rosters.manage',{cupId,teamId:t.id})).sort((a,b)=>a.name.localeCompare(b.name,'nl'));if(!teams.some(t=>t.id===teamId))teamId=teams[0]?.id;$('[data-reg-team-team]').replaceChildren(...teams.map(t=>new Option(t.name,t.id)));$('[data-reg-team-team]').value=teamId||'';if(teamId&&!roster())core.ensureRoster(cupId,teamId);
    const matches=fixtures.forCup(cupId).filter(g=>g.status!=='bye'&&[g.homeTeamId,g.awayTeamId].includes(teamId)).sort((a,b)=>Number(!['scheduled','live'].includes(a.status))-Number(!['scheduled','live'].includes(b.status))||(a.date+a.time).localeCompare(b.date+b.time));if(!matches.some(g=>g.id===matchId))matchId=matches[0]?.id||'';$('[data-reg-team-match]').replaceChildren(...(matches.length?matches.map(g=>new Option(date(g.date)+' · '+g.time+' · '+g.home+' – '+g.away,g.id)):[new Option('Nog geen wedstrijd ingepland','')]));$('[data-reg-team-match]').value=matchId;
