  root.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.regTeamTab){setTab(button.dataset.regTeamTab);return;}if(button.hasAttribute('data-reg-team-submit-roster')){change(()=>core.submitRoster(cupId,teamId),'De spelerslijst is verstuurd naar de toernooileiding.');return;}if(button.dataset.regPlayerRemove){draft=null;change(()=>core.removePlayer(cupId,teamId,button.dataset.regPlayerRemove),'Speler uit de conceptlijst verwijderd.');draft=null;return;}if(button.dataset.regPlayerEdit){const p=roster().players.find(p=>p.id===button.dataset.regPlayerEdit);if(!p)return;for(const name of ['id','firstName','lastName','birthDate','relationCode','number'])playerForm.elements[name].value=p[name]||'';editingPhoto=p.photo;renderRoster();playerForm.elements.firstName.focus();return;}if(button.hasAttribute('data-reg-player-clear'))clearPlayer();if(button.hasAttribute('data-reg-lineup-reset')){draft=null;dirty=false;lineupForm.reset();renderLineup();feedback('De laatst ingediende versie is hersteld.');}});
