  lineupForm.addEventListener('change',event=>{const row=event.target.closest('[data-reg-lineup-player]');if(!row)return;let entry=entries().find(e=>e.id===row.dataset.regLineupPlayer);if(!entry){entry={id:row.dataset.regLineupPlayer,number:1,position:'absent',captain:false,goalkeeper:false};draft.push(entry);}if(event.target.dataset.regEntry){const key=event.target.dataset.regEntry;entry[key]=key==='number'?Number(event.target.value):event.target.value;}if(event.target.name==='captain')draft.forEach(e=>e.captain=e.id===event.target.value);if(event.target.name==='goalkeeper')draft.forEach(e=>e.goalkeeper=e.id===event.target.value);dirty=true;const validation=core.validateLineup(match(),side(),draft);$('[data-reg-lineup-errors]').innerHTML=validation.errors.map(e=>'<li>'+esc(e)+'</li>').join('');$('[data-reg-lineup-errors]').hidden=!validation.errors.length;});
  lineupForm.addEventListener('submit',event=>{event.preventDefault();const result=change(()=>core.submitLineup(matchId,side(),entries(),lineupForm.elements.attested.checked,lineupForm.elements.reason.value),'De spelersopgave is ingediend voor controle door de scheidsrechter.');if(result?.ok){draft=null;dirty=false;lineupForm.reset();render();}});
