  const date=value=>new Date(value+'T12:00:00Z').toLocaleDateString('nl-NL',{day:'numeric',month:'long'}),birth=value=>new Date(value+'T12:00:00Z').toLocaleDateString('nl-NL',{day:'numeric',month:'long',year:'numeric'});
  let selectedId=store.get('refereeMatchV14','HV-2701'),officialId=store.get('refereeIdV14',''),screen='programme',filter='today',side='home',saving=false,loadedForm='',passTimer,duplicateInput=null,duplicateEventId=null;
  const game=()=>fixtures.get(selectedId),assignment=id=>window.HVOperations?.assignment?.(id)||{officialId:'sam',name:'Sam Verduin',confirmed:!!store.get('officialMatchSessions',{})[id]?.confirmed},confirmed=()=>!!assignment(selectedId).confirmed,ready=()=>regs.canStart(game()).ok,closed=()=>['finished','cancelled','walkover'].includes(game()?.status)||!!core.result(selectedId);
