  function show(next,id=selectedId){if(id!==selectedId){selectedId=id;side='home';loadedForm='';store.set('refereeMatchV14',id);}screen=next;root.dataset.matchId=selectedId;root.dataset.screen=screen;root.querySelectorAll('[data-rfo-screen]').forEach(p=>p.hidden=p.dataset.rfoScreen!==screen);$('[data-rfo-breadcrumb]').hidden=screen==='programme';$('[data-rfo-match-back]').hidden=screen==='match';$('[data-rfo-current]').textContent=screenLabels[screen]||'';feedback('');if($('[data-rfo-photo]').open)$('[data-rfo-photo]').close();render();if(!page.hidden)requestAnimationFrame(()=>root.scrollIntoView({block:'start',behavior:'instant'}));}
