  function renderMenu(){const m=game();if(!m)return;$('[data-rfo-match-meta]').textContent=m.cupName+' · '+m.round+' · '+m.id;$('[data-rfo-match-title]').textContent=m.home+' – '+m.away;$('[data-rfo-match-location]').textContent=date(m.date)+' · '+m.time+' · '+m.venue+' · '+m.field;$('[data-rfo-match-status]').textContent=labels[m.status]||m.status;const pending=core.events(selectedId).filter(e=>e.status==='provisional').length;const cards=[['assignment','Aanstelling',confirmed()?'Bevestigd':'Nog te bevestigen','Bekijk je aanstelling en bevestig de afspraak.'],['players','Spelerscontrole',ready()?'Beide opgaven goedgekeurd':'Controle vóór de aftrap','Naam, foto en geboortedatum van beide selecties.'],['clock','Wedstrijdklok',core.clock(selectedId)?.phaseLabel||'Fases en speeltijd','Beheer speelhelften, rust, verlenging en klokcorrecties.'],['shootout','Strafschoppenserie',core.shootout(selectedId).complete?'Serie beslist':'Afzonderlijke beslisprocedure','Leg iedere strafschop vast zonder gewone doelpunten te veranderen.'],['events','Wedstrijdbeeld',pending?pending+' meldingen ter controle':'Gebeurtenissen registreren','Doelpunten, kaarten, wissels en bijzonderheden.'],['result','Afronden',closed()?'Wedstrijdbeeld vastgelegd':'Na de wedstrijd','Stel het definitieve wedstrijdbeeld vast.']];$('[data-rfo-menu]').innerHTML=cards.map(([key,title,state,note],i)=>'<button type="button" class="hv-panel rfo-menu-card" data-rfo-step="'+key+'"><span class="rfo-menu-icon" aria-hidden="true">'+['✓','◎','◷','◉','▤','✓'][i]+'</span><small>'+esc(state)+'</small><h3>'+title+'</h3><p>'+note+'</p><b>Open '+title.toLowerCase()+'</b></button>').join('');window.HVCompetitionUI?.renderMatchBrief($('[data-rfo-brief]'),m);}
  function renderAssignment(){const m=game();if(!m)return;const a=assignment(selectedId);$('[data-rfo-assignment-title]').textContent=m.home+' – '+m.away;$('[data-rfo-assignment-meta]').textContent=date(m.date)+' · '+m.time+' · '+m.venue+' · '+m.field+' · '+m.id;$('[data-rfo-assignment-name]').textContent=a.name;$('[data-rfo-assignment-status]').textContent=a.confirmed?'Bevestigd':'Te bevestigen';$('[data-rfo-confirm]').hidden=a.confirmed;}
