  function render(){if(screen==='programme')renderProgramme();if(screen==='match')renderMenu();if(screen==='assignment')renderAssignment();if(screen==='players')renderPlayers();if(screen==='events')renderEvents();if(screen==='clock')renderClock();if(screen==='shootout')renderShootout();if(screen==='result')renderFinal();}
  root.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.rfoClockAction){change(()=>core.clockCommand(selectedId,button.dataset.rfoClockAction),'Klokhandeling vastgelegd.');return;}if(button.dataset.rfoClockPhase){change(()=>core.clockCommand(selectedId,'phase',{phase:button.dataset.rfoClockPhase}),'De nieuwe wedstrijdfase is vastgelegd.');return;}if(button.hasAttribute('data-rfo-link-observation')){if(duplicateInput&&duplicateEventId){const result=change(()=>core.linkObservation(selectedId,duplicateEventId,duplicateInput,{role:'referee'}),'Jouw waarneming is gekoppeld aan één bevestigde gebeurtenis.');if(result?.ok){duplicateInput=null;duplicateEventId=null;$('[data-rfo-duplicate]').hidden=true;}}return;}if(button.dataset.rfoOpen){show('match',button.dataset.rfoOpen);return;}if(button.dataset.rfoStep){show(button.dataset.rfoStep);return;}if(button.dataset.rfoBack){show(button.dataset.rfoBack);return;}if(button.dataset.rfoFilter){filter=button.dataset.rfoFilter;renderProgramme();return;}if(button.dataset.rfoSide){side=button.dataset.rfoSide;renderPlayers();return;}if(button.hasAttribute('data-rfo-confirm')){change(()=>window.HVOperations?.confirmAssignment?.(selectedId)||(()=>{const sessions=store.get('officialMatchSessions',{});store.set('officialMatchSessions',{...sessions,[selectedId]:{...sessions[selectedId],confirmed:true}});return{ok:true};})(),'Je aanstelling is bevestigd.');return;}if(button.hasAttribute('data-rfo-t60-demo')){change(()=>regs.openDemoT60(selectedId),'Het controlevenster is voor deze demonstratie geopend.');return;}if(button.hasAttribute('data-rfo-demo-seen')){change(()=>regs.checkAllPlayers(selectedId,side),'De fictieve spelers zijn als aanwezig gemarkeerd.');return;}if(button.hasAttribute('data-rfo-approve-team')){change(()=>regs.reviewLineup(selectedId,side,'approved'),'De actuele spelersopgave is goedgekeurd.');return;}if(button.hasAttribute('data-rfo-start')){change(()=>core.startMatch(selectedId),'De aftrap is geregistreerd.');return;}if(button.dataset.rfoPass){const p=core.players(selectedId,side).find(p=>p.id===button.dataset.rfoPass);if(!p||!confirmed()||!regs.t60(selectedId).open)return;$('[data-rfo-photo-img]').src=p.photo;$('[data-rfo-photo-name]').textContent=p.name;$('[data-rfo-photo-id]').textContent=p.id;$('[data-rfo-photo-birth]').textContent=birth(p.birthDate);$('[data-rfo-photo]').showModal();clearTimeout(passTimer);passTimer=setTimeout(()=>$('[data-rfo-photo]').close(),20000);return;}if(button.dataset.rfoEventConfirm)change(()=>core.confirmEvent(selectedId,button.dataset.rfoEventConfirm),'Gebeurtenis bevestigd.');if(button.hasAttribute('data-rfo-confirm-all'))change(()=>core.confirmAll(selectedId),'Alle teamregistraties zijn gecontroleerd.');});
  $('[data-rfo-official]').addEventListener('change',event=>{officialId=event.target.value;store.set('refereeIdV14',officialId);renderProgramme();});
  root.addEventListener('change',event=>{if(event.target.dataset.rfoCheck){change(()=>regs.checkPlayer(selectedId,side,event.target.dataset.rfoCheck,event.target.value),'Identiteitscontrole opgeslagen.');return;}if(event.target.closest('[data-rfo-event-form]'))renderEventForm();if(event.target.closest('[data-rfo-result-form]'))renderFinal();});$('[data-rfo-result-form]').addEventListener('input',event=>{if(['homeScore','awayScore'].includes(event.target.name))renderFinal();});
  $('[data-rfo-return-form]').addEventListener('submit',event=>{event.preventDefault();const result=change(()=>regs.reviewLineup(selectedId,side,'returned',event.currentTarget.elements.reason.value),'De opgave is teruggestuurd naar de teamleiding.');if(result?.ok)event.currentTarget.reset();});
  $('[data-rfo-event-form]').addEventListener('submit',event=>{event.preventDefault();if(eventGate())return;const f=event.currentTarget.elements,input={matchId:selectedId,type:f.type.value,side:f.side.value,playerId:f.playerId.value,relatedPlayerId:f.relatedPlayerId.value,minute:Number(f.minute.value),addedMinutes:Number(f.addedMinutes.value)||0,note:f.note.value,commandId:'HV-CMD-'+crypto.randomUUID(),allowSeparate:f.allowSeparate.checked,separateReason:f.separateReason.value};const result=change(()=>core.addEvent(input,{role:'referee'}),'Gebeurtenis als gecontroleerd vastgelegd.');if(result?.duplicate){duplicateInput=input;duplicateEventId=result.existingEventId;$('[data-rfo-duplicate-note]').textContent=(core.labels[result.existingEvent.type]||'Gebeurtenis')+' · '+(result.existingEvent.minuteDisplay||result.existingEvent.minute)+'′ · '+result.existingEvent.playerName;$('[data-rfo-duplicate]').hidden=false;}else if(result?.ok){f.note.value='';f.allowSeparate.checked=false;f.separateReason.value='';duplicateInput=null;duplicateEventId=null;$('[data-rfo-duplicate]').hidden=true;}});
