    const last=rows.length?Math.max(...rows.map(row=>mins(row.time)+(row.duration||105))):1020;
    $('[data-fd-running]').innerHTML=[['08:30','Gastverenigingen en vrijwilligers melden zich bij de ontvangstbalie.'],['09:00','Controle velden, kleedkamers, portofoons en looproutes.'],...rows.map(row=>[clock(mins(row.time)-45),'Ontvangst '+row.home+' en '+row.away+' · '+row.cupName]),...rows.map(row=>[row.time,'Aftrap '+row.cupName+' · '+row.field]),[store.get('operationsCeremony',{}).time||clock(last+15),'Prijsuitreiking na de laatste finale.']].sort((a,b)=>a[0].localeCompare(b[0])).map(([time,text])=>'<li><time>'+time+'</time><span>'+esc(text)+'</span></li>').join('');
    const state=store.get('finalday',{});$('[data-fd-public]').textContent=state.update||'Het programma verloopt volgens de centrale wedstrijdkalender.';$('[data-fd-log]').innerHTML=(state.log||[]).slice(0,8).map(item=>'<li><time>'+esc(new Date(item.at).toLocaleString('nl-NL'))+'</time><span>'+esc(item.text)+'</span></li>').join('')||'<li>De finaledag staat klaar voor de ontvangst van de finalisten.</li>';
    if(!form.contains(document.activeElement))loadForm();
    for(const attr of ['data-fd-checkin','data-fd-delay-form','data-fd-progress-form']){const f=$('['+attr+']');if(!f.contains(document.activeElement)){const current=f.elements.matchId.value;f.elements.matchId.replaceChildren(...rows.map(row=>new Option(row.cupName+' · '+row.time,row.id)));f.elements.matchId.value=rows.some(row=>row.id===current)?current:selected;}}
    const pf=$('[data-fd-progress-form]');if(!pf.contains(document.activeElement)){const progress=core.finalProgress(pf.elements.matchId.value);if(progress)for(const key of ['status','expectedKickoff','expectedEnd','actualKickoff','actualEnd'])pf.elements[key].value=progress[key]||'';}
