  $('[data-fd-update-form]').addEventListener('submit',event=>{event.preventDefault();const result=core.publishUpdate(event.currentTarget.elements.update.value);$('[data-fd-update-feedback]').textContent=result.ok?'De bezoekersupdate is gepubliceerd en verstuurd naar de inbox.':result.error;if(result.ok)event.currentTarget.reset();});
