  $('[data-fd-checkin]').addEventListener('submit',event=>{event.preventDefault();const input=Object.fromEntries(new FormData(event.currentTarget)),r=core.checkInTeam(input.matchId,input.side,input);resultMessage(r,'Ontvangst vastgelegd met tijdstip en teamgegevens.');if(r.ok)render();});
  $('[data-fd-progress-form]').addEventListener('change',event=>{if(event.target.name==='matchId'){const f=event.currentTarget,p=core.finalProgress(f.elements.matchId.value);for(const key of ['status','expectedKickoff','expectedEnd','actualKickoff','actualEnd'])f.elements[key].value=p?.[key]||'';}});
  $('[data-fd-progress-form]').addEventListener('submit',event=>{event.preventDefault();const input=Object.fromEntries(new FormData(event.currentTarget)),r=core.recordFinalProgress(input.matchId,input);resultMessage(r,'Verwachte en werkelijke tijden zijn bijgewerkt.');if(r.ok)render();});
  $('[data-fd-delay-form]').addEventListener('submit',event=>{event.preventDefault();const x=Object.fromEntries(new FormData(event.currentTarget)),r=core.saveDelayPlan(x.matchId,x.delay);resultMessage(r,'Uitloopvoorstel berekend. Controleer de gevolgen vóór publicatie.');if(!r.ok)return;delayId=r.plan.id;const p=r.plan;$('[data-fd-delay-preview]').innerHTML='<div class="ops-summary"><div><span>Voorgestelde prijsuitreiking</span><strong>'+esc(p.ceremony)+'</strong></div><span class="ops-badge">'+p.proposals.length+' finales aangepast</span></div><div class="ops-list">'+p.proposals.map(row=>'<article class="ops-row"><div><strong>'+esc(row.cupName)+'</strong><small>'+esc(row.field+' · '+row.before+' wordt '+row.time)+'</small></div><span class="ops-badge">+'+row.minutes+' min</span></article>').join('')+'</div><h3>Betrokkenen en middelen</h3><div class="ops-list">'+p.affected.map(row=>'<article class="ops-row"><div><strong>'+esc(row.teams.join(' – '))+'</strong><small>'+esc((row.official||'Official nog in te vullen')+' · kleedkamers '+row.rooms.join(' en '))+'</small></div></article>').join('')+'</div>'+(p.warnings.length?'<div class="ops-impact-warning"><strong>Opvolging nodig</strong><ul>'+p.warnings.map(w=>'<li>'+esc(w)+'</li>').join('')+'</ul></div>':'<p>Geen extra beschikbaarheidswaarschuwingen in de bekende gegevens.</p>');$('[data-fd-delay-publish]').hidden=false;});
  $('[data-fd-delay-publish]').addEventListener('submit',event=>{event.preventDefault();const r=core.publishDelay(delayId,event.currentTarget.elements.reason.value);resultMessage(r,'Uitloop gepubliceerd; kalender, betrokkenen en prijsuitreiking zijn bijgewerkt.');if(r.ok){$('[data-fd-delay-publish]').hidden=true;$('[data-fd-delay-preview]').innerHTML='<p class="ops-empty">Het voorstel is gepubliceerd. Bereken een nieuw voorstel bij verdere uitloop.</p>';render();}});

  let framePending=false;
