  const $=selector=>page.querySelector(selector),form=$('[data-supporter-filters]'),field=name=>form.elements.namedItem(name),labels={scheduled:'Gepland',live:'Live',finished:'Afgelopen',cancelled:'Afgelast',suspended:'Gestaakt',review:'In beoordeling',walkover:'Reglementair beslist',bye:'Vrijloting'};
