  form.addEventListener('submit',event=>event.preventDefault());form.addEventListener('change',()=>{if(!field('date').value||!field('date').validity.valid)field('date').value=fixtures.today;render();});
  const prefForm=$('[data-supporter-preferences]'),preferences=store.get('supporterPreferences',{goals:true,planning:true,news:false});for(const key of ['goals','planning','news'])prefForm.elements.namedItem(key).checked=preferences[key]===true;prefForm.addEventListener('submit',event=>{event.preventDefault();const next={};for(const key of ['goals','planning','news'])next[key]=prefForm.elements.namedItem(key).checked;store.set('supporterPreferences',next);$('[data-supporter-feedback]').textContent='Je meldingsvoorkeuren zijn op dit apparaat bewaard.';});
