      if(row.status==='open'&&state.role==='leadership')html+='<form class="case-decision-form" data-case-discipline-decision="'+esc(row.id)+'"><h4>Tuchtbesluit vastleggen</h4><label>Besluit<select name="decision"><option value="dismiss">Geen sanctie / dossier sluiten</option><option value="warning">Waarschuwing</option><option value="suspend-matches">Schorsing voor wedstrijden</option><option value="suspend-indefinite">Schorsing tot nader besluit</option></select></label><label data-case-sanction-matches hidden>Aantal wedstrijden<input name="sanctionMatches" type="number" min="1" max="20" value="1"></label><label>Ingang vanaf<input name="effectiveDate" type="date" min="'+esc(game.date)+'" value="'+esc(game.date)+'" required></label><label class="case-check"><input type="checkbox" name="countWalkovers" '+(core.policy(row.cupId).countWalkovers?'checked':'')+'> Reglementaire doorgang laten meetellen</label><label>Motivering<textarea name="reason" rows="3" minlength="10" maxlength="1600" required></textarea></label><button type="submit" class="hv-button hv-button-dark">Tuchtbesluit opslaan</button></form>';
