    if(form===objectionForm&&event.target.name==='teamId')objectionGate();
    if(form===objectionForm&&event.target.name==='matchId'){chosenTeams(form);objectionGate();if(state.role==='team'){state.contextMatch=event.target.value;state.detailSignatures={};store.set('caseSelectedMatch',state.contextMatch);for(const type of ['objections','incidents','discipline'])renderList(type);}}
    if(form===incidentForm&&event.target.name==='matchId')fillIncident();
    if(form===reportForm&&event.target.name==='matchId'){chosenTeams(form);updateReportPlayers();}
    if(form===reportForm&&event.target.name==='teamId')updateReportPlayers();
    if(form===regulatoryForm&&event.target.name==='matchId')chosenTeams(form);
    if(form===regulatoryForm&&event.target.name==='kind'){$('[data-case-regulatory-scores]').hidden=event.target.value==='walkover';for(const name of ['homeScore','awayScore'])field(form,name).required=event.target.value!=='walkover';}
    if(form.matches('[data-case-objection-decision]')&&event.target.name==='decision')form.querySelector('[data-case-objection-adjustment]').hidden=event.target.value!=='corrected';
    if(form.matches('[data-case-incident-decision]')&&event.target.name==='action'){form.querySelector('[data-case-incident-schedule]').hidden=!['remaining-later','replay'].includes(event.target.value);form.querySelector('[data-case-incident-result]').hidden=!['keep-result','regulatory-score','walkover','exclude-team'].includes(event.target.value);}
    if(form.matches('[data-case-discipline-decision]')&&event.target.name==='decision')form.querySelector('[data-case-sanction-matches]').hidden=event.target.value!=='suspend-matches';
