    if(form.matches('[data-case-response-form]')){readEvidence(form.querySelector('[data-case-response-files]')).then(evidence=>execute(()=>core.appendResponse(form.dataset.caseResponseForm,{...input,evidence},actor()),'Je reactie en bewijsstukken zijn aan het dossier toegevoegd.')).catch(error=>feedback(error.message,true));return;}
    if(form.matches('[data-case-assign]')){execute(()=>core.assignCase(form.dataset.caseAssign,{...input,dueAt:fromLocal(input.dueAt)}),'Behandelaar en beslistermijn bijgewerkt.');return;}
    if(form.matches('[data-case-question]')){execute(()=>core.askQuestion(form.dataset.caseQuestion,{...input,dueAt:fromLocal(input.dueAt)}),'De betrokken partij heeft een reactieverzoek ontvangen.');return;}
    if(form.matches('[data-case-close-question]')){execute(()=>core.closeQuestion(form.dataset.caseCloseQuestion,form.dataset.questionId,input.reason),'De vraag is gemotiveerd afgesloten.');return;}
    if(form.matches('[data-case-review-request]')){readEvidence(form.querySelector('[data-case-review-files]')).then(evidence=>execute(()=>core.requestReview(form.dataset.caseReviewRequest,{...input,evidence},actor()),'Herzieningsverzoek ontvangen. Het bestaande besluit blijft geldig.')).catch(error=>feedback(error.message,true));return;}
    if(form.matches('[data-case-review-decision]')){execute(()=>core.decideReview(form.dataset.caseReviewDecision,input.reviewDecision,input.reason),'Het herzieningsbesluit is vastgelegd.');return;}
    if(form===objectionForm){readEvidence(form.querySelector('[data-case-initial-files]')).then(evidence=>{const result=execute(()=>core.fileObjection(input.matchId,input.teamId,input.category,input.note,{evidence}),'Bezwaar ontvangen. Het door de scheidsrechter vastgestelde wedstrijdbeeld blijft geldig.');if(result?.ok){field(form,'note').value='';form.querySelector('[data-case-initial-files]').value='';}}).catch(error=>feedback(error.message,true));return;}
