  const $=s=>root.querySelector(s),form=$('[data-photo-form]'),field=name=>form.elements.namedItem(name),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let previewSrc='assets/action.webp',selectedFile=null,objectUrl=null;
