  function render(){const value=$('[data-history-filter]').value,editions=[...new Set(rows().map(row=>row.season))].sort().reverse();$('[data-history-filter]').replaceChildren(new Option('Alle edities',''),...editions.map(label=>new Option(label,label)));if(editions.includes(value))$('[data-history-filter]').value=value;const filtered=rows().filter(row=>!value||row.season===value);$('[data-history-editions]').innerHTML=filtered.map(row=>'<article class="history-card"><img src="assets/finale.webp" alt="Sfeerbeeld van de toernooibeker" loading="lazy"><div><p class="hv-eyebrow">Editie '+esc(row.season)+'</p><h3>'+esc(row.cupName)+'</h3><p>Winnaar</p><strong class="history-winner">'+esc(row.winner)+'</strong>'+(row.runnerUp?'<p>Finalist: '+esc(row.runnerUp)+'</p>':'')+'<dl><div><dt>Wedstrijden</dt><dd>'+esc(row.matches)+'</dd></div><div><dt>Doelpunten</dt><dd>'+esc(row.goals)+'</dd></div></dl><button type="button" class="hv-button hv-button-outline" data-history-open="'+esc(row.id)+'">Open de volledige editie</button><small>Vastgelegd · revisie '+esc(row.revision||1)+'</small></div></article>').join('')||'<p class="discover-empty">Er zijn nog geen edities afgesloten voor dit filter.</p>';if(selected)renderDossier();}
