  function navigateContext(matchId,teamId,href){const fromRole=A.context().role;const game=window.HVFixtures.get(matchId);if(!game)return;if(href.startsWith('#team')){const team=teamId||A.context().teamId||game.homeTeamId;S.setMany({teamWorkspaceV14:{cupId:game.tournamentId,teamId:team,matchId:game.id},teamLiveMatch:game.id,teamLiveTeam:team});A.demoRole('team',{teamId:team});}if(href==='#official'){const assignment=window.HVOperations.assignment(game.id);if(assignment?.officialId)A.demoRole('official',{officialId:assignment.officialId});S.set('refereeMatchV14',game.id);}if(href.startsWith('#dossiers'))S.set('caseSelectedMatch',game.id);S.set('contextNavigateV15',{matchId:game.id,teamId,cupId:game.tournamentId,href,fromRole,role:fromRole});}
  document.addEventListener('click',event=>{const link=event.target.closest('[data-hv15-action]');if(link){const task=M.tasks({role:'leadership'}).find(t=>t.id===link.dataset.hv15Action);if(task&&!task.matchId)S.set('contextNavigateV15',{taskId:task.id,teamId:task.teamId,cupId:task.cupId,href:task.href,fromRole:A.context().role,role:A.context().role});else navigateContext(link.dataset.hv15Match,link.dataset.hv15Team,link.getAttribute('href'));}const demo=event.target.closest('[data-hv-demo-role]');if(demo)A.demoRole(demo.dataset.hvDemoRole);});
