  function renderAccounts(){const picker=$(hub,'[data-hub-manage-account]'),accountId=picker.value||A.current().id;options(picker,A.accounts().map(a=>({value:a.id,label:a.name})),accountId);const rows=A.memberships().filter(m=>m.accountId===picker.value);$(hub,'[data-hub-memberships]').innerHTML=rows.map(m=>'<article class="hv15-row hv-action-row"><div class="hv-action-row__content"><h3>'+esc(A.labels[A.normalize(m.role)])+'</h3><p>'+esc(m.teamId?window.HVIdentity.team(m.teamId)?.name:m.clubId?window.HVIdentity.club(m.clubId)?.name:'Binnen de toegewezen rol')+'</p>'+status(m.status==='active'?'Actief'+(m.validUntil?' tot '+date(m.validUntil):''):'Ingetrokken',m.status==='active'?'is-done':'')+'</div>'+(m.status==='active'?'<span class="hv-row-actions"><button class="hv-row-action" data-hub-revoke="'+esc(m.id)+'" type="button"'+rowLabel('Rol intrekken: '+A.labels[A.normalize(m.role)])+'>'+rowIcon('revoke')+'</button></span>':'')+'</article>').join('');const invite=$(hub,'[data-hub-invite]');options(invite.elements.clubId,window.HVIdentity.listClubs().map(v=>({value:v.id,label:v.name})),invite.elements.clubId.value||'HV-V-101');const teams=window.HVIdentity.listTeams().filter(t=>t.clubId===invite.elements.clubId.value);options(invite.elements.teamId,teams.map(t=>({value:t.id,label:t.name})),invite.elements.teamId.value);$(hub,'[data-hub-invitations]').innerHTML=A.invitations().map(i=>'<article class="hv15-row hv-action-row"><div class="hv-action-row__content"><h3>'+esc(A.accounts().find(a=>a.id===i.accountId)?.name||'Uitgenodigde')+'</h3><p>'+esc(A.labels[i.role])+' · '+(i.status==='pending'?'Wacht op aanvaarden':'Aanvaard in de demo')+'</p></div>'+(i.status==='pending'?'<span class="hv-row-actions"><button class="hv-row-action" type="button" data-hub-accept="'+esc(i.id)+'"'+rowLabel('Uitnodiging aanvaarden in demo: '+(A.accounts().find(a=>a.id===i.accountId)?.name||'Uitgenodigde')+' · '+A.labels[i.role])+'>'+rowIcon('check')+'</button></span>':'')+'</article>').join('')||empty('Nog geen demo-uitnodigingen klaargezet.');const form=$(hub,'[data-hub-delegate]');options(form.elements.membershipId,A.memberships().filter(m=>m.status==='active'&&m.accountId===picker.value).map(m=>({value:m.id,label:A.labels[A.normalize(m.role)]+(m.teamId?' · '+window.HVIdentity.team(m.teamId)?.name:'')})),form.elements.membershipId.value);options(form.elements.accountId,A.accounts().filter(a=>a.id!==picker.value).map(a=>({value:a.id,label:a.name})),form.elements.accountId.value);}
