  function presentation(){const row=core.publicRecord(cupId),enabled=core.settings(cupId).enabled;$('[data-draw-disabled]').hidden=!!row;$('[data-draw-presentation]').hidden=!row;$('[data-draw-progress]').textContent=row?'Trekking '+(index+1)+' van '+row.pairs.length:enabled?'Nog geen gepubliceerde loting':'Optioneel · Uitgeschakeld';if(!row){stop();return;}if(lastRecord!==row.id){lastRecord=row.id;index=0;stop();}index=Math.max(0,Math.min(index,row.pairs.length-1));const pair=row.pairs[index],cup=fixtures.cups.find(c=>c.id===cupId);$('[data-draw-stage-title]').textContent=cup.name;$('[data-draw-stage-eyebrow]').textContent='Gepubliceerde loting · '+competition.roundNames[row.roundKey];$('[data-draw-stage-round]').textContent=competition.roundNames[row.roundKey]+' · '+(row.status==='published'?'Officieel gepubliceerd':'Concept');$('[data-draw-home]').textContent=pair.homeName;$('[data-draw-away]').textContent=pair.awayName;$('[data-draw-home-mark]').textContent=pair.home==='bye'?'◇':pair.homeName.split(' ').map(value=>value[0]).slice(0,3).join('');$('[data-draw-away-mark]').textContent=pair.away==='bye'?'◇':pair.awayName.split(' ').map(value=>value[0]).slice(0,3).join('');$('[data-draw-caption]').textContent=pair.bye?'Een vrijloting geeft rechtstreeks toegang tot de volgende ronde.':'De thuisspelende vereniging ontvangt de tegenstander. Op de finaledag spelen we op Houtrust.';$('[data-draw-previous]').disabled=index===0;$('[data-draw-next]').disabled=index===row.pairs.length-1;$('[data-draw-revealed]').innerHTML=row.pairs.slice(0,index+1).map((value,i)=>'<article><small>Trekking '+(i+1)+(value.bye?' · Vrijloting':'')+'</small><strong>'+esc(value.homeName)+' – '+esc(value.awayName)+'</strong><small>'+esc(competition.roundNames[row.roundKey])+'</small></article>').join('');if(!matchMedia('(prefers-reduced-motion: reduce)').matches){const stage=$('.draw-stage');stage.classList.remove('is-revealing');requestAnimationFrame(()=>stage.classList.add('is-revealing'));}}
  function render(){const cups=fixtures.cups;if(!cups.some(row=>row.id===cupId))cupId=cups[0]?.id;options($('[data-draw-cup]'),cups.map(row=>({value:row.id,label:row.name})));$('[data-draw-cup]').value=cupId||'';const cup=cups.find(row=>row.id===cupId);$('[data-draw-bracket]').href='#schema-'+(cup?.key||'senioren');$('[data-draw-management]').hidden=!allowed();const config=core.settings(cupId);$('[data-draw-enabled]').checked=config.enabled;$('[data-draw-form]').elements.avoidSameClub.checked=config.avoidSameClub;$('[data-draw-form]').elements.usePots.checked=config.usePots;const opening=cup?.bracketSize===32?'first':cup?.bracketSize===16?'last16':'quarter',rounds=competition.roundOrder.slice(competition.roundOrder.indexOf(opening));options($('[data-draw-round]'),rounds.map(key=>({value:key,label:competition.roundNames[key]})));pots();proposal();presentation();$('[data-draw-records]').innerHTML=core.records(cupId).map(row=>'<article class="draw-record-row"><time>'+esc(new Date(row.publishedAt||row.createdAt).toLocaleDateString('nl-NL',{day:'numeric',month:'short',year:'numeric',timeZone:'Europe/Amsterdam'}))+'</time><div><h3>'+esc(competition.roundNames[row.roundKey])+'</h3><p>'+esc(row.pairs.length)+' trekkingen · Sleutel: '+esc(row.seed)+'</p><p>'+esc(row.reason)+'</p></div><span>'+esc(row.status==='published'?'Gepubliceerd':'Concept')+'</span></article>').join('')||'<p>Er is nog geen loting vastgelegd voor deze beker.</p>';}
  $('[data-draw-cup]').addEventListener('change',event=>{stop();cupId=event.target.value;proposalId=null;index=0;lastRecord=null;render();});$('[data-draw-round]').addEventListener('change',pots);$('[data-draw-form]').elements.usePots.addEventListener('change',pots);
