  $('[data-draw-publish]').addEventListener('submit',event=>{event.preventDefault();const result=core.publish(proposalId,event.currentTarget.elements.reason.value);feedback(result.ok?{ok:true,message:'De loting is officieel gepubliceerd en werkt door in het bekerschema.'}:result);if(result.ok){proposalId=null;render();}});
